42	      --color-coral-rgb: 255, 107, 107;
43	      --color-cyan: #00d4ff;
44	      --color-cyan-rgb: 0, 212, 255;
45	    }
46	
47	    * {
48	      margin: 0;
49	      padding: 0;
50	      box-sizing: border-box;
51	    }
52	    html {
53	      scroll-behavior: smooth;
54	    }
55	    html, body {
56	      height: 100%;
57	    }
58	    body {
59	      display: flex;
