68	      padding: 20px;
69	    }
70	    .circle-container {
71	      cursor: pointer;
72	      border: none;
73	      background: none;
74	      padding: 0;
75	      position: relative;
76	      transition: transform var(--transition-normal), filter 0.2s ease;
77	      user-select: none;
78	      touch-action: manipulation;
79	      -webkit-tap-highlight-color: transparent;
