86	      will-change: transform, filter;
87	    }
88	    .circle-container:focus {
89	      outline: none;
90	    }
91	    .circle-container:hover {
92	      transform: scale(1.05);
93	      filter: brightness(1.1);
94	    }
95	    .circle-container:active {
96	      transform: scale(0.98);
97	    }
98	    .circle-container:focus-visible {
99	      outline: 3px solid rgba(255, 255, 255, 0.95);
100	      outline-offset: 14px;
101	      border-radius: 50%;
102	      animation: focusRingPulse 0.4s ease-out;
103	    }
104	    svg {
105	      width: min(400px, 80vw);
106	      height: min(400px, 80vw);
107	      display: block;
108	      animation: fadeIn var(--transition-slow) ease-out, hintBounce 2.5s ease-in-out 0.8s 1 backwards;
109	      will-change: transform, opacity;
110	      contain: layout paint style;
111	      backface-visibility: hidden;
112	      perspective: 1000px;
