114	    circle {
115	      fill: var(--color-white);
116	      stroke: rgba(255, 255, 255, 0.25);
117	      stroke-width: 1.5;
118	      animation: pulse var(--pulse-duration) ease-in-out infinite;
119	      filter: drop-shadow(0 20px 40px var(--shadow-color));
120	      transition: fill 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), r 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), stroke 0.4s ease, filter 0.4s ease;
121	      contain: layout paint style;
122	      will-change: fill, r, stroke, filter;
123	    }
124	    .circle-container:is(:hover, :focus-visible) circle {
125	      fill: #e8f4f8;
126	      r: 205;
127	      stroke: rgba(255, 255, 255, 0.5);
128	      filter: drop-shadow(0 20px 50px rgba(255, 255, 255, 0.2));
129	    }
130	    .circle-container.active:not([class*="color-mode-"]) circle {
