657	        { class: 'color-mode-1', name: 'Pink' },
658	        { class: 'color-mode-2', name: 'Teal' },
659	        { class: 'color-mode-3', name: 'Mint' },
660	        { class: 'color-mode-4', name: 'Purple' },
661	        { class: 'color-mode-5', name: 'Orange' },
662	        { class: 'color-mode-6', name: 'Coral' },
663	        { class: 'color-mode-7', name: 'Cyan' }
