691	        helpBtn: document.getElementById('help-btn'),
692	        helpModal: document.getElementById('help-modal'),
693	        modalClose: document.getElementById('modal-close')
694	      };
695	
696	      let state = { active: false, colorMode: 0 };
697	      let tapCount = 0;
698	      let tapTimeout = null;
